const terrain=Game.prototype.makeTerrain;Game.prototype.makeTerrain=function(){terrain.call(this);const id=this.options.layout;if(!Number.isInteger(id)||id<20||id>29)return;this.mask.fill(0);const n=id-20;for(let x=0;x<C.W;x++){const q=Math.min(x,C.W-1-x);let y=630+45*Math.sin(x*(.006+n*.0004))+22*Math.cos(x*.022+n);if(n===0)y=640+55*Math.cos(q*.014);if(n===1)y=670-Math.floor(q/130)*24;if(n===2)y=620-(q>200&&q<370?110:0)-(q>560?80:0);if(n===3)y=690-95*Math.abs(Math.sin(x*.007));if(n===4)y=650+45*Math.sin(x*.012);if(n===5)y=660-160*Math.abs(Math.sin(x*.0085))**8;if(n===6)y=605+75*Math.sin(x*.009);if(n===7)y=680-155*Math.abs(Math.sin(q*.004));if(n===8)y=650-Math.floor(q/155)*28;if(n===9)y=640-(q>190&&q<340?120:0)-(q>560?80:0);if((n===0||n===4||n===8||n===9)&&Math.abs(x-800)<55)y=900;if(q<80)y+=(80-q)*4;y=clamp(Math.floor(y),420,900);this.heights[x]=y;for(let py=y;py<C.H;py++)this.mask[py*C.W+x]=1;}
this.structures=[{x:190+n*3,y:405-n%3*15,w:120,h:28},{x:440-n*2,y:295+n%4*18,w:140,h:28},{x:695,y:185+n%3*22,w:210,h:30},{x:1020+n,y:310+n%4*15,w:140,h:28},{x:1270-n*3,y:420-n%3*15,w:125,h:28}];if(n%2)this.structures.push({x:710,y:455,w:180,h:25});for(const s of this.structures)for(let y=s.y;y<s.y+s.h;y++)this.mask.fill(1,y*C.W+s.x,y*C.W+s.x+s.w);};
function safeSites(g){return g.landingSites().filter(p=>g.alive().every(u=>Math.hypot(u.x-p.x,u.y-p.y)>65));}
Game.prototype.dropSupply=function(){const state=this.chapterState;if(!state||state.crates.length>=4)return;const sites=safeSites(this);if(!sites.length)return;const p=sites[Math.floor(this.rng()*sites.length)],kind=this.rng()<.5?'heal':'ammo';state.crates.push({x:p.x,y:55,vy:0,targetY:p.y+6,kind,landed:false});this.emit('supplyDrop',{x:p.x,y:55,kind});};
const create=C.createBattle;C.createBattle=function(o={}){const g=create({...o,chapterVersion:1}),stage=STAGES[g.options.stage],field=stage?.field||{type:rules[g.options.layout]?.[0]||'calm',value:rules[g.options.layout]?.[1]||0,label:rules[g.options.layout]?.[2]||'자유 대전'};g.options.field={...field};g.chapterState={version:1,crates:[],barrels:[],marks:[],lastTurn:g.turn,bossId:null,defeated:false};if(stage?.boss){const b=g.units[3],spec=stage.boss;Object.assign(b,{isBoss:true,bossScale:1.35,bossKind:spec.kind,name:spec.name,hp:spec.hp,maxHP:spec.hp,attack:spec.attack,skin:spec.color,skinShade:'#76617d',bossPhase:1,guardCharges:0});g.chapterState.bossId=b.id;g.options.boss={...spec};for(const u of g.units.filter(u=>u.team===1&&!u.isBoss)){u.hp=u.maxHP=80+Math.floor(stage.id/5)*5;u.name='호위 웜';}const sites=g.landingSites().filter(p=>g.alive().every(u=>u.id===3||Math.hypot(u.x-p.x,u.y-p.y)>145)&&!g.solid(p.x,p.y-58));if(sites.length)Object.assign(b,sites[Math.floor(g.rng()*sites.length)]);g.emit('bossIntro',{id:b.id,name:b.name,title:spec.title});}
const sites=safeSites(g);for(let i=0;i<Math.min(3,Math.floor((g.options.stage??0)/5)+1);i++){const p=sites[Math.floor(g.rng()*sites.length)];if(p&&g.chapterState.barrels.every(b=>Math.hypot(b.x-p.x,b.y-p.y)>125))g.chapterState.barrels.push({x:p.x,y:p.y+5,active:true});}g.dropSupply();g.applyField();return g;};
Game.prototype.applyField=function(){const f=this.options.field;if(!f)return;if(f.type==='wind')this.wind=(this.turn%4<2?1:-1)*f.value;if(f.type==='tide'&&this.turn>2)this.water=Math.max(660,this.water-f.value);};
Game.prototype.warnStrike=function(boss=false){const state=this.chapterState;if(!state||state.marks.length)return;const b=this.units[state.bossId],targets=boss?this.alive(0):[this.active];if(!targets.length)return;const count=boss&&b?.bossPhase===2?2:1;const shuffled=[...targets].sort((a,b)=>a.id-b.id);for(let i=0;i<Math.min(count,shuffled.length);i++){const u=shuffled[(this.turn+i)%shuffled.length];state.marks.push({x:u.x,y:u.y+18,r:boss?(b.bossKind==='void'?82:65):54,damage:boss?(b.bossPhase===2?24:18):this.options.field.value,team:boss?1:1-this.team,owner:boss?b.id:this.activeId,boss,kind:boss?b.bossKind:'meteor',due:this.turn+1});}this.emit('strikeWarning',{boss,text:boss?'보스 특수기 예고! 붉은 표적에서 벗어나세요.':'낙하 예고! 표적 바깥으로 이동하세요.'});};
Game.prototype.resolveStrikes=function(){const state=this.chapterState;if(!state)return;const due=state.marks.filter(m=>m.due<=this.turn);state.marks=state.marks.filter(m=>m.due>this.turn);for(const m of due){if(m.boss&&this.units[state.bossId]?.hp<=0)continue;for(const u of this.alive()){const d=Math.hypot(u.x-m.x,u.y+12-m.y);if(d>m.r)continue;this.damage(u,m.damage,m.team,'hazard');if(m.kind==='frost'){if(u.id===this.activeId){this.fuel*=.5;u.chilled=false;}else u.chilled=true;}if(m.kind==='storm'||m.kind==='void'){u.vx+=(m.x-u.x)*3;u.vy-=95;u.grounded=false;}}this.emit('strikeImpact',m);}this.checkWin();};
const next=Game.prototype.nextTurn;Game.prototype.nextTurn=function(){next.call(this);const s=this.chapterState;if(!s||this.phase==='ended')return;this.resolveStrikes();if(this.phase==='ended')return;this.applyField();const f=this.options.field,u=this.active;if(f?.type==='regen'&&u.hp>0){const amount=Math.min(f.value,u.maxHP-u.hp);u.hp+=amount;if(amount)this.emit('heal',{id:u.id,amount});}if(this.turn%4===0||(f?.type==='jump'&&this.turn%3===0))this.dropSupply();const boss=this.units[s.bossId];if(boss?.hp>0&&this.team===0&&(this.stats.teamTurns?.[0]||0)%2===0)this.warnStrike(true);else if(f?.type==='meteor'&&this.turn%3===0)this.warnStrike(false);};
const damage=Game.prototype.damage;Game.prototype.damage=function(u,n,team,kind){if(u.isBoss&&u.bossKind==='armor'&&u.bossPhase===1&&kind!=='water')n*=.8;const alive=u.hp>0;damage.call(this,u,n,team,kind);if(!u.isBoss||!alive)return;if(u.hp<=0){if(this.chapterState){this.chapterState.defeated=true;this.chapterState.marks=this.chapterState.marks.filter(m=>!m.boss);}this.emit('bossDefeated',{id:u.id,x:u.x,y:u.y});}else if(u.bossPhase===1&&u.hp<=u.maxHP*.5){u.bossPhase=2;u.attack+=.12;this.emit('bossRage',{id:u.id,x:u.x,y:u.y,name:u.name});if(u.bossKind==='void'){const sites=safeSites(this);if(sites.length){const p=sites[Math.floor(this.rng()*sites.length)],from={x:u.x,y:u.y};Object.assign(u,p,{vx:0,vy:0,grounded:true});this.emit('teleport',{id:u.id,...p,from});}}}};
const jump=Game.prototype.jump;Game.prototype.jump=function(){const attached=!!this.rope,ok=jump.call(this);if(ok&&!attached&&this.options.field?.type==='jump')this.active.vy*=this.options.field.value;return ok;};
const unit=Game.prototype.stepUnit;Game.prototype.stepUnit=function(u,dt){const f=this.options.field,oldVX=u.vx,grounded=u.grounded;if(f?.type==='gravity'&&this.options.layout!==17&&!this.rope&&!u.grounded)u.vy-=430*(1-f.value)*dt;unit.call(this,u,dt);if(f?.type==='ice'&&grounded&&u.grounded){if(this.input&&u.id===this.activeId&&this.canMove())u.vx=this.input*30;else if(Math.abs(oldVX)>1&&Math.sign(u.vx)===Math.sign(oldVX))u.vx=oldVX*Math.pow(f.value,dt);}};
const advance=Game.prototype.advanceProjectile;Game.prototype.advanceProjectile=function(p,dt,predict=false){const f=this.options.field,from={x:p.x,y:p.y};if(!p.stuck&&WEAPONS[p.weapon].kind!=='sniper'){if(f?.type==='gravity'&&this.options.layout!==17)p.vy-=290*(1-f.value)*dt;if(f?.type==='magnet'&&Math.hypot(p.x-800,p.y-280)<430)p.vx+=clamp((800-p.x)*.7,-f.value,f.value)*dt;}const result=advance.call(this,p,dt,predict);if(!WEAPONS[p.weapon].fuse&&!p.child){const dx=p.x-from.x,dy=p.y-from.y,len=dx*dx+dy*dy;let first=null;for(const b of this.chapterState?.barrels||[]){if(!b.active)continue;const t=len?clamp(((b.x-from.x)*dx+(b.y-8-from.y)*dy)/len,0,1):0;if(Math.hypot(from.x+dx*t-b.x,from.y+dy*t-(b.y-8))<15&&(!first||t<first.t))first={t};}if(first){p.x=from.x+dx*first.t;p.y=from.y+dy*first.t;return 'explode';}}return result;};
const explode=Game.prototype.explode;Game.prototype.explode=function(p){explode.call(this,p);const barrels=this.chapterState?.barrels;if(!barrels||['beacon','disc'].includes(WEAPONS[p.weapon].kind))return;let centers=[{x:p.x,y:p.y,r:WEAPONS[p.weapon].radius+18}];while(centers.length){const c=centers.shift();for(const b of barrels)if(b.active&&Math.hypot(b.x-c.x,b.y-8-c.y)<c.r){b.active=false;const bomb={x:b.x,y:b.y-8,owner:p.owner,team:p.team,weapon:0,damageScale:p.damageScale??1};this.blast(bomb,32,58);this.emit('barrelBlast',{x:b.x,y:b.y-8});centers.push({x:b.x,y:b.y-8,r:95});}}};
const step=Game.prototype.step;Game.prototype.step=function(dt=C.STEP){if(this.paused||this.phase==='ended')return;step.call(this,dt);const state=this.chapterState;if(!state||this.phase==='ended')return;for(const box of state.crates){if(!box.landed){box.vy=Math.min(85,box.vy+50*dt);box.y+=box.vy*dt;if(box.y>=box.targetY){box.y=box.targetY;box.landed=true;}}else if(!this.solid(box.x,box.y+12)){box.y+=70*dt;if(this.solid(box.x,box.y+12))box.y=Math.floor(box.y);}if(box.y+10>this.water){box.used=true;continue;}const u=this.alive().find(u=>Math.hypot(u.x-box.x,u.y-box.y)<34&&(box.kind==='heal'?u.hp<u.maxHP:this.ammo[u.team][1]<4));if(u&&box.landed){box.used=true;if(box.kind==='heal'){const amount=Math.min(25,u.maxHP-u.hp);u.hp+=amount;this.emit('heal',{id:u.id,amount});}else this.ammo[u.team][1]++;this.emit('supplyPickup',{id:u.id,x:box.x,y:box.y,kind:box.kind});}}state.crates=state.crates.filter(b=>!b.used);};
